head.script:
/************************************************************************************
 * ID           :	ULDSTF09043
 * File         :	ULDSTF09043.xml
 * Name         :	(팝업)매매거래정지 지정
 * Author       :	Inswave
 * Description  :	상장형 수익증권 투자유의종목 매매거래정지 지정(정지구분 0) 팝업 — 부모 ULDSTF09340 탭6
 * Create Date  :	2026-10-30
 *
 * 원본 : ui/completed/ULDSTF09043/ULDSTF09043.xml — W-Craft 1차 변환 + API 적용 개발 사본(이미 현대식, meta_asisFileNm ULDSTF05320.gfm)
 * 업무 분석 : ui/completed/ULDSTF09043/ULDSTF09043.md (같은 계열 09042·09043·09044 3본 중 하나)
 *  - 부모는 openPopup data 로 평면 키를 넘기고, 이 화면은 $c.data.getParameter() 로 받는다.
 *  - 부모 화면을 직접 부르던 refreshParent 는 없애고, 저장·삭제가 한 건이라도 되면 닫힐 때 { isSaved : true } 로 알린다.
 *  - 공시안내문작성(ULDSTF92024)은 openPopup data 로 넘기고 await 한다. 92024 가 아직 부모 getPar 를 부르므로 호환용 scwin.getPar 를 둔다.
************************************************************************************/

///////// 1. 변수 및 선언 영역 /////////

scwin.screenId = "ULDSTF09043";

// 부모 화면(ULDSTF09340)에서 넘겨받는 값 — 업무 분석 §1.2
scwin.isurCd = "";          // 부모 목록에서 고른 회사코드
scwin.isurNm = "";          // 회사명
scwin.secugrpId = "";       // 증권그룹ID (PF: 상장형 수익증권)
scwin.mktId = "";           // 시장구분 (받기만 함)
scwin.bzProcsNo = "";       // 업무처리번호 — 비어 있으면 신규, 있으면 수정
scwin.haltTpCd = "";        // 정지구분 (이 화면은 0: 지정)
scwin.selectGubun = "";     // 상세 조회 구분(1:종목, 2:발행회사, 3:전체)
scwin.fstDtectDd = "";      // 최초지정일(최초적출일)
scwin.designDd = "";        // 매매거래정지일 기본값
scwin.inqDd = "";           // 조회기준일 — 현재일보다 앞이면 조회 전용
scwin.rsnCd = "";           // 정지사유 기본 코드 (신규: 424)
scwin.rsnNm = "";           // 정지사유 기본 내용
scwin.rsnDsc = "";          // 정지사유 설명 (받기만 함)
scwin.remk = "";            // 기타 기본 문구
scwin.isuCd = "";           // 부모 목록에서 고른 종목코드 — 신규일 때 종목선택 가능 여부 판정에 쓴다
scwin.isuNm = "";           // 종목명

// 화면 상태값
scwin.trJob = "";           // 처리구분 I: 저장, U: 수정, D: 삭제
scwin.curDate = "";         // 서버 현재일 (yyyyMMdd)
scwin.isSaved = false;      // 저장·수정·삭제가 한 건이라도 성공했는지 — 닫힐 때 부모 재조회 판단
scwin.dsclRow = -1;         // 공시안내문작성 대상 그리드 행

// 고정값
scwin.LIST_BZ_RSN_CD_424 = "424";   // 투자유의종목(상장형 수익증권) 정지사유
scwin.DESIGN_CD = "01";             // 중복 확인·전문의 투자유의 지정구분코드 (개발 사본 값 유지 — 업무 분석 §10)
scwin.LIST_BZ_TP_CD = {             // 증권그룹별 상장업무유형코드 (개발 사본 값 유지 — 업무 분석 §10)
    EN : "716",
    EF : "750",
    PF : "816"
};
scwin.DSCL_FORM_CD = "69809";       // 공시안내문 서식코드
scwin.DSCL_MKT_ID = "1";            // 공시안내문 시장구분
scwin.RSN_MKT_IDX = "1";            // 사유선택(ULDSTF92007) 시장구분
scwin.RSN_RSN_IDX = "06";           // 사유선택(ULDSTF92007) 사유구분 — 매매거래정지

// 이 화면의 역할→버튼 매핑 — 상태별 활성 정책은 공통(BTN_STATE_MAP)이 보유한다.
scwin.BTN_MAP = {
    save : "btn_save",          // [저장]
    modify : "btn_update",      // [수정]
    "delete" : "btn_delete",    // [삭제]
    guide : "btn_dscl"          // [안내문작성]
};


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 30
 * @description 페이지로드 — scwin.init 만 부른다.
 * @param
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09043.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 30
 * @description 초기화. 날짜 입력 검사를 걸고, 부모 파라미터로 신규·수정을 가른 뒤 신규면 기본값을 채우고 수정이면 상세를 조회한다.
 *
 * 부모(ULDSTF09340)는 openPopup 의 3번째 인자를 평면으로 넘기므로 $c.data.getParameter() 로 전체를 받아 키를 바로 읽는다.
 * @param
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 단일 달력 날짜 검사 (규칙 37)
    $c.date.checkCalendarFormat(edt_TrdHaltStrtDd, "yyyyMMdd", "매매거래정지일");

    scwin.curDate = $c.date.getServerDateTime();

    const param = $c.data.getParameter() ?? {};

    scwin.isurCd = param.isurCd ?? "";
    scwin.isurNm = param.isurNm ?? "";
    scwin.secugrpId = param.secugrpId ?? "";
    scwin.mktId = param.mktId ?? "";
    scwin.bzProcsNo = param.bzProcsNo ?? "";
    scwin.haltTpCd = param.haltTpCd ?? "";
    scwin.selectGubun = param.selectGubun ?? "";
    scwin.fstDtectDd = param.fstDtectDd ?? "";
    scwin.designDd = param.designDd ?? "";
    scwin.inqDd = param.inqDd ?? "";
    scwin.rsnCd = param.rsnCd ?? "";
    scwin.rsnNm = param.rsnNm ?? "";
    scwin.rsnDsc = param.rsnDsc ?? "";
    scwin.remk = param.remk ?? "";
    scwin.isuCd = param.isuCd ?? "";
    scwin.isuNm = param.isuNm ?? "";

    // 신규면 조회할 것이 없다. 기본값을 채우고 종목선택을 기다린다.
    if ($c.util.isEmpty(scwin.bzProcsNo)) {
        scwin.initNewForm();
        scwin.setFormState();
        return;
    }

    await scwin.selectOne();
};

/**
 * @method
 * @name scwin.initNewForm
 * @author Inswave
 * @date 2026. 10. 30
 * @description 신규 진입 기본값. 정지일은 부모가 넘긴 값(없으면 현재일), 기타는 부모 문구, 정지사유는 부모가 넘긴 기본 사유 한 행이다.
 * @param
 * @returns
 * @hidden N
 */
scwin.initNewForm = function () {
    dma_mst.setEmptyValue();
    dlt_isuTemp.removeAll();
    dlt_rsn.removeAll();

    dma_mst.set("trdHaltStrtDd", $c.util.isEmpty(scwin.designDd) ? scwin.curDate : scwin.designDd);
    dma_mst.set("remk", scwin.remk);
    dma_mst.set("fstDtectDd", scwin.fstDtectDd);

    // 정지사유 기본값
    dlt_rsn.insertRow();
    dlt_rsn.setCellData(0, "haltRsnCd", scwin.rsnCd);
    dlt_rsn.setCellData(0, "haltRsnNm", scwin.rsnNm);
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.img_SetIsuCd_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 종목선택 클릭. 종목선택(ULDSTF09047)이 돌려준 종목 목록으로 그리드를 통째로 바꾼다.
 *
 * 팝업이 돌려준 종목은 전부 이번에 새로 지정하는 종목(addYn Y)이다.
 * 반환이 배열이 아니거나(취소·X 닫기) 비면 취소로 보고 그대로 둔다(묶음 A 09341~09345 와 같은 판정).
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.img_SetIsuCd_onclick = async function (e) {
    try {
        const param = {
            srchType : "pfAll",
            isuList : dlt_isuTemp.getAllJSON()      // 09047 은 읽지 않는다(업무 분석 §10)
        };

        const result = await $c.lc.popFindPfCode(param);

        // 고른 종목 목록(배열)만 받는다. 배열이 아니거나(취소·X 닫기 { isCloseButtonClick }) 비면 취소다.
        if (!Array.isArray(result) || result.length === 0) return;
        const rows = result;

        dlt_isuTemp.removeAll();
        dlt_isuTemp.setJSON(rows.map(row => ({ ...row, addYn : "Y", status : "" })));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09043.img_SetIsuCd_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_rsn_add_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 사유추가 클릭. 사유선택(ULDSTF92007)에서 고른 사유로 정지사유 첫 행을 바꾸고 근거규정을 채운다(원본과 같이 한 행만 유지).
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_rsn_add_onclick = async function (e) {
    try {
        const res = await scwin.openRsnPopup();

        if (res?.isCloseButtonClick || $c.util.isEmpty(res?.code)) return;

        if (dlt_rsn.getRowCount() === 0) dlt_rsn.insertRow();
        dlt_rsn.setCellData(0, "haltRsnCd", res.code);
        dlt_rsn.setCellData(0, "haltRsnNm", res.name);
        dma_mst.set("trdHaltGrndRegulNm", res.regl ?? "");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09043.btn_rsn_add_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_rsn_del_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 사유삭제 클릭. 정지사유 그리드에서 고른 행을 지운다.
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_rsn_del_onclick = async function (e) {
    try {
        const row = dlt_rsn.getRowPosition();

        if (row < 0) {
            await $c.win.alert($c.data.getMessage("com_req_select", "사유"));
            return;
        }
        dlt_rsn.removeRow(row);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09043.btn_rsn_del_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_save_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 저장 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_save_onclick = async function (e) {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09043.btn_save_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_update_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 수정 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_update_onclick = async function (e) {
    try {
        await scwin.update();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09043.btn_update_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_delete_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 삭제 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_delete_onclick = async function (e) {
    try {
        await scwin.remove();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09043.btn_delete_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_dscl_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 안내문작성 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_dscl_onclick = async function (e) {
    try {
        await scwin.writeDscl();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09043.btn_dscl_onclick" });
    }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.selectOne
 * @author Inswave
 * @date 2026. 10. 30
 * @description 업무처리번호로 상세를 조회해 마스터·정지사유·종목을 받고, 종목을 그리드에 옮긴 뒤 버튼 상태를 정한다.
 * @param
 * @returns
 * @hidden N
 */
scwin.selectOne = async function () {
    dma_mst.setEmptyValue();

    const sbmOptions = {
        id : "sbm_selectOne",
        method : "get",
        action : "/api/listing/lstproc/pf/invst-warn-trdsusprls-dsgnrls/select-one",
        target : "dma_mst=body.mstDto, dlt_rsn=body.rsnDto, dlt_isu=body.isuDto",
        isProcessMsg : false
    };

    const requestData = {
        bzProcsNo : scwin.bzProcsNo,        // 업무처리번호
        gubun : scwin.selectGubun,          // 조회구분 (1:종목, 2:발행회사, 3:전체)
        isurCd : scwin.isurCd               // 발행기관코드
    };

    // 통신 오류는 공통 오류 핸들러가 안내하고 예외를 던진다.
    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);

    if (!result.responseJSON?.success) return;

    scwin.bzProcsNo = dma_mst.get("bzProcsNo");

    // 수정·삭제는 그리드 행 단위로 돌기 때문에 조회한 종목도 그리드에 둔다.
    dlt_isuTemp.removeAll();
    dlt_isuTemp.setJSON(dlt_isu.getAllJSON());

    scwin.setFormState();
};

/**
 * @method
 * @name scwin.checkDuplicate
 * @author Inswave
 * @date 2026. 10. 30
 * @description 그리드의 종목마다 같은 기준일에 이미 지정돼 있는지 서버에 확인한다. 하나라도 중복이면 안내하고 true 를 돌려준다.
 * @param
 * @returns {Promise<Boolean>} 중복 종목 존재 여부
 * @hidden N
 */
scwin.checkDuplicate = async function () {
    const rowCount = dlt_isuTemp.getRowCount();

    for (let i = 0; i < rowCount; i++) {
        dma_chk.setEmptyValue();

        const sbmOptions = {
            id : "sbm_checkDuplicate",
            method : "get",
            action : "/api/listing/lstproc/pf/invst-warn/select-duplicate",
            target : "dma_chk=body",
            isProcessMsg : false
        };

        const requestData = {
            etpInvstwarnDesignCd : scwin.DESIGN_CD,            // 지정구분코드
            basDd : scwin.inqDd,                               // 기준일
            isuCd : dlt_isuTemp.getCellData(i, "isuCd")        // 종목코드
        };

        const result = await $c.sbm.executeDynamic(sbmOptions, requestData);

        if (!result.responseJSON?.success) continue;

        if (dma_chk.get("dupChk") === "Y") {
            await $c.win.alert("[" + dlt_isuTemp.getCellData(i, "isuNm") + "] 중복된 종목이 저장되어 있습니다.");
            return true;
        }
    }

    return false;
};

/**
 * @method
 * @name scwin.saveOne
 * @author Inswave
 * @date 2026. 10. 30
 * @description 그리드 한 행을 전문 마스터(dma_mst)에 옮겨 담아 저장(I)·수정(U)·삭제(D)하고, 결과를 그 행의 status 에 남긴다.
 *
 * 세 처리는 전문이 같고 action 만 다르다. 성공한 행에만 업무처리번호를 기록한다.
 * 전송 구조(행마다 호출하며 isuDto 에 그리드 전체 종목을 싣는 것)는 개발 사본 그대로다 — 업무 분석 §10 #1.
 * @param {String} trJob 처리구분 I: 저장, U: 수정, D: 삭제
 * @param {Number} row 그리드 행 index
 * @param {String} bzProcsNo 이 행의 업무처리번호 (신규는 채번한 값)
 * @returns {Promise<Boolean>} 처리 성공 여부
 * @hidden N
 */
scwin.saveOne = async function (trJob, row, bzProcsNo) {
    scwin.copyRowToMap(row, bzProcsNo);

    for (let i = 0; i < dlt_rsn.getRowCount(); i++) {
        dlt_rsn.setCellData(i, "bzProcsNo", bzProcsNo);
        dlt_rsn.setCellData(i, "ulyHaltYn", "N");
    }

    for (let i = 0; i < dlt_isuTemp.getRowCount(); i++) {
        dlt_isuTemp.setCellData(i, "bzProcsNo", bzProcsNo);
    }

    dma_mst.set("haltDesnrelsTpCd", "0");     // 0:지정, 1:해제, 2:지정및해제

    const svcId = { I : "insert", U : "update", D : "delete" }[trJob];
    const requestMap = {
        bzProcsNo : bzProcsNo,
        count : "3",
        listBzTpCd : $c.lc.getGlbValue("LIST_BZ_TP_CD_813"),
        mstDto : dma_mst.getJSON(),
        isuDto : dlt_isuTemp.getAllJSON(),
        rsnDto : dlt_rsn.getAllJSON()
    };

    // 처리구분별 전체 경로 리터럴 (규칙 38)
    const actions = {
        insert : "/api/listing/lstproc/pf/invst-warn-trdsusp-dsgn/insert",
        update : "/api/listing/lstproc/pf/invst-warn-trdsusp-dsgn/update",
        "delete" : "/api/listing/lstproc/pf/invst-warn-trdsusp-dsgn/delete"
    };
    const sbmOptions = {
        id : "sbm_saveOne",
        method : "post",
        action : actions[svcId],
        mediatype : "application/json",
        isProcessMsg : false
    };

    // 통신 오류는 공통 오류 핸들러가 안내하고 예외를 던진다. 그러면 남은 행은 처리하지 않는다.
    const result = await $c.sbm.executeDynamic(sbmOptions, requestMap);

    const isSuccess = (result.responseJSON?.success === true);

    if (isSuccess) {
        dlt_isuTemp.setCellData(row, "bzProcsNo", bzProcsNo);
    }
    dlt_isuTemp.setCellData(row, "status", isSuccess ? "Y" : "N");

    return isSuccess;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.setFormState
 * @author Inswave
 * @date 2026. 10. 30
 * @description 신규·수정·조회기준일 경과에 따라 종목선택 가능 여부와 버튼 상태를 정한다.
 *  - 신규(업무처리번호 없음)         : [저장]만 활성, 종목선택은 부모가 종목을 넘기지 않은 경우만 가능
 *  - 수정(조회기준일이 현재일 이후)  : [수정]·[삭제]·[안내문작성] 활성
 *  - 조회기준일 경과                 : 전 버튼 잠금, 종목선택 잠금
 * @param
 * @returns
 * @hidden N
 */
scwin.setFormState = function () {
    const isNew = $c.util.isEmpty(scwin.bzProcsNo);

    // 조회기준일이 현재일보다 앞선 건은 조회 전용이다.
    const isReadOnly = !isNew && !$c.util.isEmpty(scwin.inqDd) && scwin.inqDd < scwin.curDate;

    img_SetIsuCd.setDisabled(isReadOnly || !(isNew && $c.util.isEmpty(scwin.isuCd)));

    let status = "update";

    if (isNew) {
        status = "insert";
    } else if (isReadOnly) {
        status = "disabled";
    }

    $c.util.setButtonState("grpBtnBox", status, scwin.BTN_MAP);
};

/**
 * @method
 * @name scwin.validate
 * @author Inswave
 * @date 2026. 10. 30
 * @description 저장·수정 전 입력값을 검증한다. 종목·정지사유 행 유무를 먼저 보고, 입력 항목은 공통 검증(validateDataCollect)으로,
 * 신규 저장의 중복 지정은 서버 확인으로 본다.
 * @param
 * @returns {Promise<Boolean>} 검증 통과 여부
 * @hidden N
 */
scwin.validate = async function () {
    if (dlt_isuTemp.getRowCount() === 0) {
        await $c.win.alert($c.data.getMessage("com_req_select", "종목"));
        img_SetIsuCd.focus();
        return false;
    }

    if (dlt_rsn.getRowCount() === 0) {
        await $c.win.alert($c.data.getMessage("com_req_select", "정지사유"));
        btn_rsn_add.focus();
        return false;
    }

    const options = {
        validateType : "alert",
        checkType : "single",
        fields : {
            edt_TrdHaltStrtDd : { required : true, format : "date", name : "매매거래정지일" },
            txa_InvstwarnContn : { required : true, maxLength : 200, name : "근거규정" },
            txa_Remk : { maxLength : 2000, name : "기타" }
        }
    };

    if (!await $c.validate.validateDataCollect(panel_1, options)) return false;

    // 신규 저장은 같은 종목이 이미 지정돼 있는지 서버에 확인한다.
    if (scwin.trJob === "I" && await scwin.checkDuplicate()) return false;

    return true;
};

/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 10. 30
 * @description 신규 저장. 투자유의 사유(424) 신규면 공시 순서를 안내하고, 검증과 확인을 거친 뒤 그리드의 종목을 한 건씩 저장한다.
 * @param
 * @returns
 * @hidden N
 */
scwin.save = async function () {
    scwin.trJob = "I";

    if (scwin.rsnCd === scwin.LIST_BZ_RSN_CD_424 && $c.util.isEmpty(scwin.bzProcsNo)) {
        await $c.win.alert("투자유의종목 지정과 투자유의종목 매매거래정지 및 정지해제가\r\n" +
            "동시에 공시되는 경우 투자유의종목 지정 공시가 먼저 최종 승인\r\n" +
            "되어야 합니다.(지정 공시가 제출까지 완료되어야 함)");
    }

    if (!await scwin.validate()) return;

    // "[저장] 처리를 하시겠습니까?" 확인
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    await scwin.processRows(scwin.trJob);
};

/**
 * @method
 * @name scwin.update
 * @author Inswave
 * @date 2026. 10. 30
 * @description 수정. 검증과 확인을 거친 뒤 그리드의 종목을 한 건씩 수정한다.
 * @param
 * @returns
 * @hidden N
 */
scwin.update = async function () {
    scwin.trJob = "U";

    if (!await scwin.validate()) return;

    if (!await $c.lc.isProcess(scwin.trJob)) return;

    await scwin.processRows(scwin.trJob);
};

/**
 * @method
 * @name scwin.remove
 * @author Inswave
 * @date 2026. 10. 30
 * @description 삭제. 확인을 거친 뒤 그리드의 종목을 한 건씩 삭제한다. 전부 성공하면 processRows 가 팝업을 닫는다.
 * @param
 * @returns
 * @hidden N
 */
scwin.remove = async function () {
    scwin.trJob = "D";

    if (dlt_isuTemp.getRowCount() === 0) {
        await $c.win.alert($c.data.getMessage("com_req_select", "종목"));
        img_SetIsuCd.focus();
        return;
    }

    if (!await $c.lc.isProcess(scwin.trJob)) return;

    await scwin.processRows(scwin.trJob);
};

/**
 * @method
 * @name scwin.processRows
 * @author Inswave
 * @date 2026. 10. 30
 * @description 그리드의 종목을 한 건씩 순차 전송하고, 결과를 안내한 뒤 화면 상태를 맞춘다.
 *  - 신규는 행마다 업무처리번호를 채번한다(14자리). 채번 실패 행은 실패로 남기고 다음 행으로 간다.
 *  - 한 건이라도 처리되면 scwin.isSaved 를 세워 닫힐 때 부모가 다시 조회하게 한다(원본 refreshParent 대체).
 *  - 실패가 있으면 실패를 안내하고, 삭제는 성공한 행을 지워 실패한 행만 남긴다.
 *  - 전부 성공하면 완료를 안내하고, 삭제는 { isSaved : true } 로 팝업을 닫으며, 저장·수정은 수정 상태로 버튼을 맞춘다.
 * @param {String} trJob 처리구분 I: 저장, U: 수정, D: 삭제
 * @returns
 * @hidden N
 */
scwin.processRows = async function (trJob) {
    const rowCount = dlt_isuTemp.getRowCount();
    let errCnt = 0;

    for (let i = 0; i < rowCount; i++) {
        let bzProcsNo = dlt_isuTemp.getCellData(i, "bzProcsNo");

        if (trJob === "I") {
            bzProcsNo = String(await $c.stf.getNewBzProcNo() ?? "");

            if (bzProcsNo.length !== 14) {
                await $c.win.alert($c.data.getMessage("com_complete_0151", "업무처리번호생성"));
                dlt_isuTemp.setCellData(i, "status", "N");
                errCnt++;
                continue;
            }
        }

        if (!await scwin.saveOne(trJob, i, bzProcsNo)) errCnt++;
    }

    const jobNm = { I : "저장", U : "수정", D : "삭제" }[trJob];

    if (errCnt < rowCount) scwin.isSaved = true;

    if (errCnt > 0) {
        await $c.win.alert($c.data.getMessage("com_complete_0151", jobNm));

        // 삭제는 성공한 행을 지워 실패한 행만 남긴다. 뒤에서부터 지워야 index 가 밀리지 않는다.
        if (trJob === "D") {
            for (let i = dlt_isuTemp.getRowCount() - 1; i >= 0; i--) {
                if (dlt_isuTemp.getCellData(i, "status") === "Y") dlt_isuTemp.removeRow(i);
            }
        }
        return;
    }

    await $c.win.alert($c.data.getMessage("com_complete_0096", jobNm));

    if (trJob === "D") {
        await $c.win.closePopup({ isSaved : true });
        return;
    }

    // 저장이 성공한 뒤에야 수정 모드가 된다. 다건이면 첫 행의 번호를 화면 상태값으로 둔다.
    scwin.bzProcsNo = dlt_isuTemp.getCellData(0, "bzProcsNo");
    scwin.setFormState();
};

/**
 * @method
 * @name scwin.copyRowToMap
 * @author Inswave
 * @date 2026. 10. 30
 * @description 그리드 한 행의 종목 정보와 화면 고정값을 전문 마스터(dma_mst)에 담는다.
 *
 * 정지일·근거규정·기타는 입력 항목이 dma_mst 에 바인딩돼 있어 이미 들어 있다.
 * 최초지정일은 부모가 넘긴 최초적출일, 없으면 이번 매매거래정지일이다(원본 fn_Instwarn_fstdd 의 대체값 — 업무 분석 §8).
 * @param {Number} row 그리드 행 index
 * @param {String} bzProcsNo 이 행의 업무처리번호
 * @returns
 * @hidden N
 */
scwin.copyRowToMap = function (row, bzProcsNo) {
    dma_mst.set("bzProcsNo", bzProcsNo);
    dma_mst.set("isuCd", dlt_isuTemp.getCellData(row, "isuCd"));
    dma_mst.set("isuNm", dlt_isuTemp.getCellData(row, "isuNm"));
    dma_mst.set("isurCd", dlt_isuTemp.getCellData(row, "isurCd"));
    dma_mst.set("addYn", dlt_isuTemp.getCellData(row, "addYn"));

    dma_mst.set("etpInvstwarnDesignCd", scwin.DESIGN_CD);
    dma_mst.set("listBzTpCd", scwin.LIST_BZ_TP_CD[scwin.secugrpId] ?? "");
    dma_mst.set("basDd", scwin.inqDd);
    dma_mst.set("fstDesignDd", $c.util.isEmpty(scwin.fstDtectDd) ? dma_mst.get("trdHaltStrtDd") : scwin.fstDtectDd);
};

/**
 * @method
 * @name scwin.openRsnPopup
 * @author Inswave
 * @date 2026. 10. 30
 * @description 매매거래정지사유 선택 팝업(ULDSTF92007)을 열고 고른 사유를 돌려받는다.
 * pcc $c.lc.popFindLstRsnCd 는 콜백형이라 반환값이 없어 화면에서 직접 연다(선례 sample-front ULDSTF08052).
 * @param
 * @returns {Promise<Object>} { code, name, regl } — 취소·X 닫기면 { isCloseButtonClick }
 * @hidden N
 */
scwin.openRsnPopup = async function () {
    const options = {
        id : "ULDSTF92007",
        popupName : "매매거래정지사유 선택",
        width : 520,
        height : 345,
        type : "pageFramePopup"
    };
    const data = {
        mktIdx : scwin.RSN_MKT_IDX,
        rsnIdx : scwin.RSN_RSN_IDX
    };

    return await $c.win.openPopup("/ui/lst/common/ULDSTF92007.xml", options, data);
};

/**
 * @method
 * @name scwin.getDsclRow
 * @author Inswave
 * @date 2026. 10. 30
 * @description 공시안내문작성 대상 행. 종목이 한 건이면 그 행, 여럿이면 그리드에서 고른 행이다. 없거나 저장 전이면 안내하고 -1.
 * @param
 * @returns {Promise<Number>} 그리드 행 index (없으면 -1)
 * @hidden N
 */
scwin.getDsclRow = async function () {
    const rowCount = dlt_isuTemp.getRowCount();
    const row = (rowCount === 1) ? 0 : grd_list.getFocusedRowIndex();

    if (rowCount === 0 || row < 0) {
        await $c.win.alert($c.data.getMessage("com_req_select", "종목"));
        return -1;
    }

    if ($c.util.isEmpty(dlt_isuTemp.getCellData(row, "bzProcsNo"))) {
        await $c.win.alert("저장한 뒤 안내문을 작성해 주세요.");
        return -1;
    }

    return row;
};

/**
 * @method
 * @name scwin.getDsclData
 * @author Inswave
 * @date 2026. 10. 30
 * @description 공시안내문작성(ULDSTF92024)에 넘길 값. 원본 편집기 호출이 넘기던 서식코드·업무처리번호·발행기관코드·시장구분과
 * 대상 종목·마스터다(arr[4]·arr[5] 는 원본 근거가 없어 넘기지 않음 — 업무 분석 §10).
 * @param {Number} row 대상 그리드 행 index
 * @returns {Object} 넘길 data
 * @hidden N
 */
scwin.getDsclData = function (row) {
    return {
        formCd : scwin.DSCL_FORM_CD,                            // arr[0]
        bzProcsNo : dlt_isuTemp.getCellData(row, "bzProcsNo"),  // arr[1]
        isurCd : dlt_isuTemp.getCellData(row, "isurCd"),        // arr[2]
        mktId : scwin.DSCL_MKT_ID,                              // arr[3]
        isu : [dlt_isuTemp.getRowJSON(row)],
        mst : [dma_mst.getJSON()]
    };
};

/**
 * @method
 * @name scwin.writeDscl
 * @author Inswave
 * @date 2026. 10. 30
 * @description 공시안내문작성. 대상 행을 정해 팝업을 data 로 넘겨 열고 닫힐 때까지 기다린다(닫힌 뒤 재조회 없음).
 * @param
 * @returns
 * @hidden N
 */
scwin.writeDscl = async function () {
    const row = await scwin.getDsclRow();
    if (row < 0) return;

    scwin.dsclRow = row;

    const options = {
        id : "ULDSTF92024",
        popupName : "공시안내문작성",
        width : 745,
        height : 820,
        type : "pageFramePopup"
    };

    // TODO: 92024 는 아직 부모 getPar 계약이라 수신부 변경 필요 (업무 분석 §10)
    await $c.win.openPopup("/ui/listingcommon/ULDSTF92024.xml", options, scwin.getDsclData(row));
};

/**
 * @method
 * @name scwin.getPar
 * @author Inswave
 * @date 2026. 10. 30
 * @description [호환용 · 임시] 공시안내문작성(ULDSTF92024) 전환본은 아직 부모의 scwin.getPar 를 이름으로 불러 값을 받는다.
 * 92024 가 $c.data.getParameter() 수신으로 바뀌면 이 함수를 지운다. (가이드 §6.5 예외, 선례 ULDSTF05918)
 * @param {Array} arr 92024 가 넘기는 빈 배열 — [0] 서식코드 [1] 업무처리번호 [2] 발행기관코드 [3] 시장구분 을 채운다(4칸 → 본문 생성)
 * @param {Object} dltIsu 92024 의 종목 dataList
 * @param {Object} dltMst 92024 의 마스터 dataList
 * @returns {Number} arr 길이
 * @hidden N
 */
scwin.getPar = function (arr, dltIsu, dltMst) {
    const data = scwin.getDsclData(scwin.dsclRow);

    arr[0] = data.formCd;
    arr[1] = data.bzProcsNo;
    arr[2] = data.isurCd;
    arr[3] = data.mktId;

    scwin.fillDataList(dltIsu, data.isu);
    scwin.fillDataList(dltMst, data.mst);

    return arr.length;
};

/**
 * @method
 * @name scwin.fillDataList
 * @author Inswave
 * @date 2026. 10. 30
 * @description 컬럼 정의가 비어 있는 92024 의 원천 dataList 에 행 키를 컬럼으로 더하고 행을 채운다. (원본 CopyDataSet 의 헤더 복사)
 * @param {Object} dataList 채울 dataList
 * @param {Array} rows 행 배열
 * @returns
 * @hidden N
 */
scwin.fillDataList = function (dataList, rows) {
    if (!dataList) return;

    Object.keys(rows[0] ?? {}).forEach(key => {
        if (dataList.getColumnIndex(key) < 0) dataList.insertColumn(key);
    });
    dataList.setJSON(rows);
};
